`timescale 1ns/1ns

module tb_traffic_light;

// === Global Sync Signal ===
reg llm_go_signal = 1;


  reg clk;
  reg rst_n;
  reg pass_request;
  wire [7:0] clock;
  wire red;
  wire yellow;
  wire green;
  integer i;
  // Instantiate the module
  traffic_light uut (
    .clk(clk), 
    .rst_n(rst_n),
    .pass_request(pass_request), 
    .clock(clock), 
    .red(red),
    .yellow(yellow),
    .green(green)
  );

  // Clock generation
  always begin
    #5 clk = ~clk;
  end

  integer error = 0;
  integer clock_cnt;
  // Test sequence
  initial begin
    clk = 0; // Initialize clock
    rst_n = 1; // De-assert reset
    pass_request = 0; // No pass request initially

    // Perform reset
    rst_n = 0;
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

    #10;
    rst_n = 1;
    #30;

    // test red
    $display("At time %t, clock = %d, red = %b, yellow = %b, green = %b", 
               $time, clock, red, yellow, green);
    error = (red==1)&&(yellow==0)&&(green==0) ?error :error+1;
    #100;
    // test green
    $display("At time %t, clock = %d, red = %b, yellow = %b, green = %b", 
               $time, clock, red, yellow, green);
    error = (red==0)&&(yellow==0)&&(green==1) ?error :error+1;
    #600;
    // test yellow
    $display("At time %t, clock = %d, red = %b, yellow = %b, green = %b", 
               $time, clock, red, yellow, green);
    error = (red==0)&&(yellow==1)&&(green==0) ?error :error+1;
    #150;
    $display("At time %t, clock = %d, red = %b, yellow = %b, green = %b", 
               $time, clock, red, yellow, green);
    clock_cnt = clock;
    // test pass_request
    #30;
    $display("At time %t, clock = %d, red = %b, yellow = %b, green = %b", 
               $time, clock, red, yellow, green);
    error = (clock!=(clock_cnt+3)) ?error :error+1;
    pass_request = 1;
    #10;
    $display("At time %t, clock = %d, red = %b, yellow = %b, green = %b", 
               $time, clock, red, yellow, green);
    error = (clock==10)&&(green==1) ?error :error+1;
    if (error == 0) begin
      $display("===========Your Design Passed===========");
    end
    else begin
    $display("===========Failed===========", error);
    end

    $finish; // End of test
  end





        ///////////////////added
        integer file_mantra;
        initial begin
          file_mantra = $fopen("output.txt");//added
          $fwrite(file_mantra, "time, ");
      $fwrite(file_mantra, "clock,");
      $fwrite(file_mantra, "red,");
      $fwrite(file_mantra, "yellow,");
      $fwrite(file_mantra, "green,");

          $fwrite(file_mantra, "\n");//added
          forever begin
            #1
            $fwrite(file_mantra, "%0d, ", $time);
        $fwrite(file_mantra, "%h, ", clock);
        $fwrite(file_mantra, "%h, ", red);
        $fwrite(file_mantra, "%h, ", yellow);
        $fwrite(file_mantra, "%h, ", green);

            $fwrite(file_mantra, "\n");
          end
        end





// ============================================
// === LLM Enhanced Stimuli (Phase 1) ===
initial begin
    // [Auto-Moved Vars]
        integer i;

    // 1. DECLARE VARIABLES FIRST (Top of block)


    // 2. THEN WAIT for original tests
    wait(llm_go_signal == 1);

    // 3. THEN execute logic
    // Initialize inputs
    pass_request = 0;
    rst_n = 0;

    // Wait for clock to stabilize and hold reset
    // We synchronize to the existing clock generator
    repeat(5) @(posedge clk);

    // Release Reset
    rst_n = 1;

    // --- Test Phase 1: Red State & Invalid Pass Request ---
    // State transitions: Idle -> s1_red
    // In s1_red, p_red=1. Next cycle red=1. cnt loads 10.
    // We attempt pass_request here. It should be ignored because green=0.
    repeat(2) @(posedge clk); 
    pass_request = 1;
    repeat(2) @(posedge clk);
    pass_request = 0;

    // Wait for Red state to complete (cnt counts down from 10 to 3)
    // We consumed ~4 cycles. Need ~4-6 more. Adding buffer to ensure transition to Green.
    repeat(10) @(posedge clk);

    // --- Test Phase 2: Green State & Valid Pass Request ---
    // State transitions: s1_red -> s3_green
    // In s3_green, p_green=1. Next cycle green=1. cnt loads 60.
    // Wait a few cycles into Green to ensure cnt > 10
    repeat(5) @(posedge clk);

    // Assert pass_request. Condition: pass_request && green && (cnt > 10)
    // This should force cnt <= 10, significantly shortening the Green state.
    pass_request = 1;
    @(posedge clk);
    pass_request = 0;

    // --- Test Phase 3: Shortened Green & Yellow State ---
    // Green should now finish quickly (cnt 10 -> 3).
    // Then transition to s2_yellow.
    // Yellow loads cnt=5.
    // Wait for Green to finish and Yellow to finish.
    // Green: ~7 cycles. Yellow: ~2 cycles. Total ~10-15 cycles.
    repeat(15) @(posedge clk);

    // --- Test Phase 4: Async Reset ---
    // We should be back in Red or transitioning.
    // Assert reset to verify recovery to Idle.
    rst_n = 0;
    repeat(3) @(posedge clk);
    rst_n = 1;

    // Allow some time to restart and stabilize
    repeat(5) @(posedge clk);

    // 4. Handover to Original Testbench
    llm_go_signal = 0;
end
// ============================================


// === Global Watchdog ===

// === Global Safety Watchdog (Injected) ===
initial begin
    #200000;
    $display("\n[Watchdog] Timeout triggered at %t!", $time);
    if (file_mantra != 0) $fclose(file_mantra);
    $finish;
end

endmodule

